import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"62、【小過】 艮下震上","description":"周易口訣義 - 62、【小過】 艮下震上","frontmatter":{"title":"62、【小過】 艮下震上","description":"周易口訣義 - 62、【小過】 艮下震上"},"headers":[],"relativePath":"classics/koujueyi/064.md","filePath":"classics/koujueyi/064.md"}'),r={name:"classics/koujueyi/064.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_62、【小過】-艮下震上" tabindex="-1">62、【小過】 艮下震上 <a class="header-anchor" href="#_62、【小過】-艮下震上" aria-label="Permalink to “62、【小過】 艮下震上”">​</a></h1><p>彖曰：「小過」，小者過而亨也。過以「利貞」，與時行也。柔得中，是以小事吉也；剛失位而不中，是以不可大事也。有飛鳥之象焉，「飛鳥遺之音，不宜上，宜下，大吉」，上逆而下順也。</p><p>象曰：山上有雷，小過，君子以行過乎恭，喪過乎哀，用過乎儉。</p><p>初六，飛鳥以兇。</p><p>象曰：「飛鳥以兇」，不可如何也。</p><p>六二，過其祖，遇其妣；不及其君，遇其臣，無咎。</p><p>象曰：「不及其君」，臣不可過也。</p><p>九三，弗過防之，從或戕之，兇。</p><p>象曰：「從或戕之」，兇如何也！</p><p>九四，無咎，弗過遇之，往厲必戒，勿用永貞。</p><p>象曰：「弗過遇之」，位不當也。「往厲必戒」，終不可長也。</p><p>六五，密雲不雨，自我西郊，公弋取彼在穴。</p><p>象曰：「密雲不雨」，已上也。</p><p>上六，弗遇過之，飛鳥離之，兇，是謂災眚。</p><p>象曰：「弗遇過之」，已亢也。</p><p>解讀</p><p>「小過亨利貞」者，「小過」者，過於小事，故謂「小過」也；以小事而濟用，物乃可通，故曰「亨」也；順時矯俗，利在歸正，故曰「利貞」也。「可小事，不可大事」者，世既小通，即可正以小事，不可正以大事也。「飛鳥遺之音，不宜上，宜下，大吉」者，鳥之所棲，止於林澤，飛而向上，則入杳冥，羽翮摧頹，遺其音響，哀以思處，願求所安，故不止則愈困，下則棲於林藪，故曰「不宜上，宜下，大吉」也。此論上乘剛，逆也；下承陽，順也；故君子為過矯之行，上則逆鱗，下則執柔守順，故以飛鳥上下而取義焉。</p><p>象曰「山上有雷，小過」者，雷本出震於地上，今既出至山上，過其本處，故曰「小過」也。「君子以行過乎恭，喪過乎哀，用過乎儉」者，小過之世，戒其所過，小人居之，則慢易奢僭，故君子為過矯之行，過乎恭敬；喪孝之禮，過乎哀慼；費用之宜，過於儉約之謂也。</p><p>「初六，飛鳥以兇」者，小過之義，上逆下順，初應在四，若往就四，則是進於逆也，同於飛鳥，上而無所措足，所以致兇。</p><p>「六二，過其祖，遇其妣，不及其君，遇其臣，無咎」者，過而得之，謂其遇也。六二居初之上，而居中位，是過於初而遇六二也。祖，始也，謂初也；妣，母之稱也。六二居中履正，故謂之「妣」矣。己過初遇二位，遇母之內處，故曰「過其祖，遇其妣」。而得位處中，不至於僭，終守臣位，安可有咎？故曰「不及其君，遇其臣，無咎」也。</p><p>「九三，弗過防之，從或戕之，兇」者，小過之世，大者不能立德，故令小者僭過，驕慢陵上也。九三以陽當位，又處下卦之上，固合防遏小人，不令奢僭，而九三更應上六，與小人同情，反為小人所害也，故曰「弗過防之，從或戕之，兇」也。戕者，殺害之義也。</p><p>「九四，無咎，弗過遇之，往厲必戒，勿用永貞」者，居小過之世，小人有過差之行，須大德之人防閒遏絕，不令過差。今九四雖復陽爻而不居位，故其所過咎，責不在己，故得「無咎」。九四所以得免咎者，以其失位在上卦之下，不為過厚之行，故得遇其無咎之宜，故曰「無咎」。弗過，遇之也。既無防止遏制之能，自守其位，則免咎而已。若有所往，則致危厲，故曰「往厲」也。不交於物，物亦不親，既無人相親，是無援助，欲有所往，必致危厲，無所告救，故必自戒慎，以全其身，故曰「必戒」也。既不能裁製小人，亦不可任用，以其如此，故不足長行其正，故曰「弗用永貞」也。</p><p>六五，密雲不雨，自我西郊，公弋取彼在穴者。小過者，小過於大也。陰居陽位，是小者過於大，陰之盛矣。陰止於上，陽氣不通，雖復至盛，密雲止在西郊，而不能降其雨。以人事明之，是陰柔之主，以處尊位，未能施其風教，恩惠及下，故曰「密雲不雨，自我西郊」也。公者，臣之極貴也。五極陰盛，故稱「公」也。小過之時，其過猶小，是不能大作，猶為隱伏。以小德之才，治小過之失，能獲在穴隱伏之物，又如公之弋獵而獲隱伏之獸，故曰「公弋取彼在穴」也。</p><p>上六：弗遇過之，飛鳥離之，兇。是謂災眚者，處於小過之極，是小人過甚，不知限際，隨至穴極，過至穴，無所復遇，故曰「弗遇過之」也。以小人之行，不守限量，過而不已，遂遭害網，亦如飛鳥飛而不已，無所棲託，必罹矰繳，所以兇矣，故曰「飛鳥離之，兇」。過於亢極，以罹其兇，是謂不慎其身，災眚斯及，復何恨哉？故曰「是為災眚」。王注：過至於亢，將何所遇？飛而不已，將何所託也？</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
